SELECT id, start_date, end_date, FIRST_VALUE(monthly_fee, TRUE) OVER (PARTITION BY plan, customer_id ORDER BY monthly_fee, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_monthly_fee, RANK() OVER w_ordered AS monthly_fee_rank, AVG(monthly_fee) OVER w_recent AS monthly_fee_avg_6_prior FROM subscriptions WHERE YEAR(start_date) >= 2024 WINDOW w_ordered AS (PARTITION BY status ORDER BY monthly_fee DESC NULLS FIRST), w_recent AS (PARTITION BY YEAR(start_date), status ORDER BY end_date, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING)
